import{_ as e,o as t,c as a,f as s}from"./index.fb8fc4c4.js";const i=s('<div class="barner sm:h-96 lg:h-auto flex items-center p-8 md:px-10 lg:px-20 w-full" data-v-3f04ba25><div class="flex items-center w-full" data-v-3f04ba25><h1 class="text-primary text-4xl lg:text-6xl leading-none font-extrabold tracking-tight" data-v-3f04ba25><span class="text-blue" data-v-3f04ba25>CAMeC-CCI</span> <br data-v-3f04ba25> V\xE9ritables outils pour <br data-v-3f04ba25> l\u2019am\xE9lioration du climat <br data-v-3f04ba25> des affaires </h1><div class="right-section hidden lg:flex w-2/5" data-v-3f04ba25></div></div></div><div class="p-6 md:p-10 lg:p-12 xl:p-20" data-v-3f04ba25><div class="text-center" data-v-3f04ba25><h2 class="text-3xl tracking-tight font-bold text-gray-900 sm:text-4xl" data-v-3f04ba25> CAMeC-CCI </h2><p class="text-lg text-center tracking-tight leading-7 text-subtitlegray mt-6" data-v-3f04ba25> Le Centre d\u2019Arbitrage, de M\xE9diation et de Conciliation de la Chambre de Commerce et d\u2019Industrie du B\xE9nin (CAMeC - CCIB) est un organe mis \xE0 la disposition des commer\xE7ants, industriels et hommes d\u2019affaires pour faciliter le r\xE8glement des litiges n\xE9s de leurs relations d\u2019affaires. Les modes alternatifs de r\xE8glement des litiges mis en \u0153uvre par le CAMeC-CCIB sont l\u2019arbitrage, la m\xE9diation et la conciliation. </p></div><div class="py-16 flex flex-wrap grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8" data-v-3f04ba25><div class="card p-5 md:p-10 rounded-lg" data-v-3f04ba25><div class="mb-4" data-v-3f04ba25><span class="badge text-sm mb-4 text-green w-auto" data-v-3f04ba25>1</span></div><h2 class="text-blue text-3xl mb-4 leading-7 font-semibold" data-v-3f04ba25>L\u2019arbitrage</h2><p class="text-lg tracking-tight leading-7 text-subtitlegray" data-v-3f04ba25> L\u2019arbitrage d\xE9signe la technique visant \xE0 faire donner la solution d&#39;une question, int\xE9ressant les rapports entre deux ou plusieurs personnes, par une ou plusieurs autres personnes - l&#39;arbitre ou les arbitres - lesquelles tiennent leurs pouvoirs d&#39;une convention priv\xE9e et statuent sur la base de cette convention, sans \xEAtre investies de cette mission par l&#39;\xC9tat. </p></div><div class="card p-5 md:p-10 rounded-lg" data-v-3f04ba25><div class="mb-4" data-v-3f04ba25><span class="badge text-sm mb-4 text-green w-auto" data-v-3f04ba25>2</span></div><h2 class="text-blue text-3xl mb-4 leading-7 font-semibold" data-v-3f04ba25>La m\xE9diation</h2><p class="text-lg tracking-tight leading-7 text-subtitlegray" data-v-3f04ba25> La m\xE9diation d\xE9signe la technique visant \xE0 faire donner la solution d&#39;une question, int\xE9ressant les rapports entre deux ou plusieurs personnes, par une ou plusieurs autres personnes - l&#39;arbitre ou les arbitres - lesquelles tiennent leurs pouvoirs d&#39;une convention priv\xE9e et statuent sur la base de cette convention, sans \xEAtre investies de cette mission par l&#39;\xC9tat. </p></div><div class="card p-5 md:p-10 rounded-lg" data-v-3f04ba25><div class="mb-4" data-v-3f04ba25><span class="badge text-sm mb-4 text-green w-auto" data-v-3f04ba25>3</span></div><h2 class="text-blue text-3xl mb-4 leading-7 font-semibold" data-v-3f04ba25>La conciliation</h2><p class="text-lg tracking-tight leading-7 text-subtitlegray" data-v-3f04ba25> La conciliation, comme la m\xE9diation est un mode non juridictionnel, un processus amiable de r\xE8glement des litiges dans lequel, les parties recherchent ensemble \xE0 \xE9tablir les bases d\u2019un accord avec l\u2019aide d\u2019un tiers ind\xE9pendant appel\xE9 conciliateur. Elle s\u2019ach\xE8ve comme la m\xE9diation par la r\xE9daction d\u2019un protocole d\u2019Accord. </p></div></div><div class="px-0 lg:px-20" data-v-3f04ba25><div class="lg:px-20 px-0" data-v-3f04ba25><div class="w-full rounded-lg p-4 md:p-8 bg-gray flex flex-wrap justify-between items-center" data-v-3f04ba25><div class="w-3/4 pr-4 mb-4" data-v-3f04ba25><h2 class="text-2xl md:text-3xl tracking-tight font-bold text-gray-900 sm:text-4xl" data-v-3f04ba25> Voulez vous en savoir plus ? </h2><p class="mt-3 text-lg text-subtitlegray sm:mt-4" data-v-3f04ba25> Connectez-vous sur notre plateforme imPULSE pour avoir plus de d\xE9tails et \xE9ventuellement prendre contact avec un de nos conseillers </p></div><div class="w-auto" data-v-3f04ba25><a href="#" class="flex items-center justify-center px-4 py-2 text-lg font-medium rounded-md text-primary bg-white hover:bg-primary hover:text-white md:py-2.5 md:text-lg md:px-5" data-v-3f04ba25> Aller sur impulse.bj </a></div></div></div></div></div>',2),l=[i],d={__name:"arbitrage-mediation",setup(n){return(r,o)=>(t(),a("main",null,l))}},u=e(d,[["__scopeId","data-v-3f04ba25"]]);export{u as default};
